import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> dict with side, price, qty, active
    seq = 0
    trades = []

    def top_sell():
        while sell_heap:
            price, s, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return price, s, oid
        return None

    def top_buy():
        while buy_heap:
            negprice, s, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return -negprice, s, oid
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o and o['active']:
                o['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                t = top_sell()
                if t is None:
                    break
                sp, s, sid = t
                if price is not None and sp > price:
                    break
                so = book[sid]
                trade_qty = min(remaining, so['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                so['qty'] -= trade_qty
                if so['qty'] == 0:
                    so['active'] = False

            if typ == 'limit':
                if remaining > 0:
                    seq += 1
                    book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': True}
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    book[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'active': False}
        else:
            while remaining > 0:
                t = top_buy()
                if t is None:
                    break
                bp, s, bid = t
                if price is not None and bp < price:
                    break
                bo = book[bid]
                trade_qty = min(remaining, bo['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                bo['qty'] -= trade_qty
                if bo['qty'] == 0:
                    bo['active'] = False

            if typ == 'limit':
                if remaining > 0:
                    seq += 1
                    book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': True}
                    heapq.heappush(sell_heap, (price, seq, oid))
                else:
                    book[oid] = {'side': 'sell', 'price': price, 'qty': 0, 'active': False}

    return trades

